"""Closest Binary Search Tree Value — descend, keeping the best candidate.

Ties go to the smaller value, so the update is guarded by a strict improvement
plus a value comparison.

Time: O(h)   Space: O(1)
"""
if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Solution:
    def closestValue(self, root, target: float) -> int:
        best = root.val
        node = root
        while node:
            gap, best_gap = abs(node.val - target), abs(best - target)
            if gap < best_gap or (gap == best_gap and node.val < best):
                best = node.val
            node = node.left if target < node.val else node.right
        return best
